#!/usr/bin/env python3
"""Запись правок: акты, пропавшие вместе с удалёнными разделами, возвращены в ответ
(пункт в «Правовую основу», абзац в подходящий раздел либо раздел целиком из 30db505).
Уже применено; повторный запуск не нужен."""
import subprocess, re, sys, os
os.chdir(os.path.dirname(os.path.abspath(__file__)) + '/..')
sys.path.insert(0, 'tools')
import norm25 as N
def rd(q): return open('adp2/q%03d.txt' % q, encoding='utf-8').read().split('\n')
def wr(q, L):
    t = re.sub(r'\n{3,}', '\n\n', '\n'.join(L))
    # перенумеровать заголовки
    k = [0]
    def f(m): k[0] += 1; return '## %d. ' % k[0]
    t = re.sub(r'(?m)^## \d+\. ', f, t)
    open('adp2/q%03d.txt' % q, 'w', encoding='utf-8').write(t)
isb = lambda s: bool(re.match(r'\s*(-|\d+\.)\s', s))
def bounds(L, sub):
    hs = [i for i, l in enumerate(L) if l.startswith('## ') and sub.lower() in l.lower()]
    assert hs, sub
    i = hs[0]
    j = next((k for k in range(i + 1, len(L)) if L[k].startswith('## ') or L[k].startswith('!! ')), len(L))
    return i, j
def end(q, sub, text):
    """text — в конец раздела, заголовок которого содержит sub"""
    L = rd(q); i, j = bounds(L, sub)
    k = j - 1
    while not L[k].strip(): k -= 1
    last = L[k]
    if isb(text) and isb(last):
        if last.rstrip().endswith(';'): text = text.rstrip('.') + '.' ; L[k] = last  # прежний пункт остаётся с «;»
        L[k + 1:k + 1] = [text]
    else:
        L[k + 1:k + 1] = ['', text]
    print('q%03d [%s] после: …%s\n      + %s' % (q, L[i][:40], last[-90:], text[:110]))
    wr(q, L)
def pb(q, text): end(q, 'равовая основа', text)
def sec(q, pref, keep=None):
    """вернуть раздел из 30db505 (keep — какие строки раздела оставить) на прежнее место"""
    o = N.old(q).split('\n'); L = rd(q)
    i = next(k for k, l in enumerate(o) if l.startswith('## ') and N.hk(l).startswith(pref))
    j = next((k for k in range(i + 1, len(o)) if o[k].startswith('## ') or o[k].startswith('!! ')), len(o))
    body = [x for x in o[i + 1:j] if x.strip() == '' or keep is None or keep(x)]
    body = [x.replace('УК РФа Российской Федерации', 'Уголовного кодекса Российской Федерации') for x in body]
    # место: перед первым из следующих прежних разделов, который сохранился; иначе перед «!!»
    cur = {N.hk(l): k for k, l in enumerate(L) if l.startswith('## ')}
    pos = None
    for k in range(j, len(o)):
        if o[k].startswith('## ') and N.hk(o[k]) in cur: pos = cur[N.hk(o[k])]; break
    if pos is None: pos = next((k for k, l in enumerate(L) if l.startswith('!! ')), len(L))
    L[pos:pos] = [o[i], ''] + body + ['']
    print('q%03d раздел «%s» возвращён: %d сл.' % (q, N.hk(o[i])[:50], sum(len(x.split()) for x in body)))
    wr(q, L)
PL21 = '- //Постановление Пленума Верховного Суда РФ от 28.06.2022 № 21//: суд проверяет, являются ли применённые меры обоснованными, разумными и необходимыми для достижения законной цели и не приводят ли они к чрезмерному обременению граждан и организаций (//п. 17//).'
P19 = '//Постановление Пленума Верховного Суда РФ от 27.09.2012 № 19 «О применении судами законодательства о необходимой обороне и причинении вреда при задержании лица, совершившего преступление»//'
def main():
    end(1, 'Правовая основа и принципы', '«Руководство деятельностью МВД России осуществляет Президент Российской Федерации» (//п. 4 Положения о Министерстве внутренних дел Российской Федерации, утв. Указом Президента РФ от 21.12.2016 № 699//). В территориальных органах МВД России на окружном и региональном уровнях учреждена должность заместителя начальника территориального органа — начальника полиции (//п. 4 Указа Президента РФ от 01.03.2011 № 250 «Вопросы организации полиции»//).')
    end(2, 'Роль полиции', '**Иные субъекты.** На войска национальной гвардии возложено «участие в охране общественного порядка, обеспечении общественной безопасности» (//п. 1 ч. 1 ст. 2 Федерального закона от 03.07.2016 № 226-ФЗ//). Охрана общественного порядка и обеспечение общественной безопасности — основные направления профилактики правонарушений (//п. 4, 5 ч. 1 ст. 6 Федерального закона от 23.06.2016 № 182-ФЗ//). Участие граждан в охране общественного порядка — «оказание гражданами помощи органам внутренних дел (полиции) и иным правоохранительным органам» (//п. 1 ст. 2 Федерального закона от 02.04.2014 № 44-ФЗ//).')
    sec(3, 'Административно-правовые режимы')
    pb(3, PL21)
    pb(3, '- //Постановление Пленума Верховного Суда РФ от 24.03.2005 № 5// (//п. 18//): доказательства, полученные с нарушением закона, использовать нельзя.')
    end(5, 'Гарантии соблюдения', '- **Недопустимость доказательств.** Верховный Суд РФ разъяснил, что «нарушением, влекущим невозможность использования доказательств, может быть признано получение объяснений лица», которому не были предварительно разъяснены его права и обязанности, включая положения //ст. 51 Конституции РФ// (//п. 18 постановления Пленума Верховного Суда РФ от 24.03.2005 № 5 «О некоторых вопросах, возникающих у судов при применении Кодекса Российской Федерации об административных правонарушениях»//).')
    end(6, 'Содержание принципа беспристраст', '- Предоставление отдельным лицам незаконных привилегий и льгот по признакам пола, расы, национальности, имущественного и должностного положения или по иным обстоятельствам может свидетельствовать о нарушении условий содержания в местах принудительного содержания (//п. 3 постановления Пленума Верховного Суда РФ от 25.12.2018 № 47//).')
    end(7, 'Содержание принципа', 'Порядок отчётов должностных лиц установлен //Инструкцией по организации и проведению отчётов должностных лиц территориальных органов МВД России, утв. приказом МВД России от 26.12.2023 № 1011//.')
    end(7, 'Содержание принципа', '**Обращения граждан.** При рассмотрении обращения гражданин вправе «знакомиться с документами и материалами, касающимися рассмотрения обращения», и получать письменный ответ по существу поставленных вопросов (//п. 2 и 3 ст. 5 Федерального закона от 02.05.2006 № 59-ФЗ «О порядке рассмотрения обращений граждан Российской Федерации»//); письменное обращение регистрируется в течение трёх дней (//ч. 2 ст. 8//) и рассматривается в течение 30 дней со дня регистрации (//ч. 1 ст. 12// того же закона).')
    sec(8, 'Иные механизмы', keep=lambda x: x.startswith('**Работа с обращениями') or x.startswith('**«Горячая линия»') or x.startswith('**Этические требования'))
    end(10, 'Банки данных', '- «Обработка персональных данных осуществляется в соответствии с требованиями, установленными законодательством Российской Федерации в области персональных данных» (//ч. 7 ст. 17 Закона о полиции//); «персональные данные — любая информация, относящаяся к прямо или косвенно определённому или определяемому физическому лицу» (//п. 1 ст. 3 Федерального закона от 27.07.2006 № 152-ФЗ «О персональных данных»//).')
    end(11, 'Порядок создания', 'Для сотрудников эти решения влекут кадровые последствия, урегулированные //Федеральным законом от 30.11.2011 № 342-ФЗ «О службе в органах внутренних дел Российской Федерации и внесении изменений в отдельные законодательные акты Российской Федерации»//: перевод на иную должность, зачисление в распоряжение, а при невозможности перевода — увольнение в связи с сокращением должности.')
    end(12, 'Руководство полицией', '**Начальник территориального органа на районном уровне** назначается руководителем территориального органа на региональном уровне (//п. 12 Типового положения о территориальном органе МВД России на районном уровне, утв. приказом МВД России от 05.06.2017 № 355//).')
    pb(13, '- //Указ Президента РФ от 01.03.2011 № 250 «Вопросы организации полиции»//: называет подразделения, входящие в состав полиции, в том числе дежурные части (//подп. «а» п. 1//).')
    end(14, 'Законность (ст. 6)', 'Верховный Суд Российской Федерации разъяснил, что органы и лица, наделённые публичными полномочиями, связаны законом, а законность их решений и действий нельзя рассматривать лишь как формальное соответствие требованиям правовых норм (//п. 17 постановления Пленума Верховного Суда РФ от 28.06.2022 № 21//).')
    sec(15, 'Организация деятельности МВД', keep=lambda x: x.startswith('**Центральный аппарат.'))
    end(19, 'Правовая основа административной', 'По правовой основе административная деятельность отличается от иных видов деятельности полиции: административная — Закон о полиции, КоАП РФ и иные акты административного законодательства; уголовно-процессуальная — Уголовно-процессуальный кодекс РФ; оперативно-разыскная — //Федеральный закон от 12.08.1995 № 144-ФЗ «Об оперативно-розыскной деятельности»//.')
    pb(20, '- //Постановление Пленума Верховного Суда РФ от 28.06.2022 № 21//: законность решений и действий органов, наделённых публичными полномочиями, нельзя рассматривать лишь как формальное соответствие требованиям правовых норм (//п. 17//).')
    end(21, 'Пределы усмотрения', 'Усмотрения нет там, где норма императивна: заявления и сообщения о преступлениях, правонарушениях, происшествиях подлежат обязательному приёму независимо от места и времени события и полноты сведений (//п. 1 ч. 1 ст. 12 Закона о полиции//; //п. 8 Инструкции, утв. приказом МВД России от 29.08.2014 № 736//).')
    end(21, 'Пределы усмотрения', 'Одной из форм превышения должностных полномочий признаётся совершение действий, которые могут быть совершены только при наличии особых обстоятельств, указанных в законе или подзаконном акте (//п. 19 постановления Пленума Верховного Суда РФ от 16.10.2009 № 19//), — то есть именно ошибочная или недобросовестная оценка оснований.')
    pb(22, '- //Постановление Пленума Верховного Суда РФ от 28.06.2022 № 21//: суд проверяет, принят ли акт на основании закона, во исполнение законной цели и с соблюдением пределов полномочий (//п. 17//).')
    end(24, 'Организационно-правовые формы', '**Официальное предостережение.** Объявляется лицу «при отсутствии оснований для привлечения его к уголовной или административной ответственности и содержит обязательное для исполнения требование о недопустимости» действий, создающих условия для совершения правонарушений, либо продолжения антиобщественного поведения (//ч. 1 ст. 20 Закона о профилактике//; //п. 12 ч. 1 ст. 13 Закона о полиции//; //п. 2 Порядка объявления официального предостережения (предостережения) о недопустимости действий, создающих условия для совершения правонарушений, либо недопустимости продолжения антиобщественного поведения, утв. приказом МВД России от 04.03.2020 № 119//).')
    for q in (25, 26, 27, 29, 30): pb(q, PL21)
    pb(28, '- //Постановление Пленума Верховного Суда РФ от 24.03.2005 № 5 «О некоторых вопросах, возникающих у судов при применении Кодекса Российской Федерации об административных правонарушениях»// (//п. 21//): наказание назначается в пределах санкции; назначить наказание ниже низшего предела или не предусмотренное законом нельзя.')
    pb(29, '- //Федеральный закон от 25.07.2002 № 115-ФЗ «О правовом положении иностранных граждан в Российской Федерации»//: документами, удостоверяющими личность иностранного гражданина, «являются паспорт иностранного гражданина либо иной документ, установленный федеральным законом или признаваемый в соответствии с международным договором Российской Федерации» (//п. 1 ст. 10//).')
    pb(29, '- //Правила дорожного движения, утв. постановлением Правительства РФ от 23.10.1993 № 1090//: водитель обязан иметь при себе и по требованию сотрудников полиции передавать им для проверки водительское удостоверение, регистрационные документы на транспортное средство, а в установленных случаях — путевой лист, документы на перевозимый груз (//п. 2.1.1//).')
    pb(30, '- //Положение об условиях содержания, нормах питания и порядке медицинского обслуживания задержанных лиц в территориальных органах Министерства внутренних дел Российской Федерации, утв. постановлением Правительства РФ от 16.04.2012 № 301//: условия содержания, нормы питания и порядок медицинского обслуживания задержанных.')
